"""Only used to drive an isolated emulator's fresh test database, never packaged."""
from pathlib import Path
p=Path('qa-main.py')
s=p.read_text()
s=s.replace('acceso = DialogoAcceso(sesion, ventana)', "acceso = DialogoAcceso(sesion, ventana)\nQTimer.singleShot(2000, lambda: (acceso.password.setText('Admin'), acceso.validar()))")
s=s.replace('# Pantalla de espera automática', "print('ANDROID_QA_LOGIN', bool(sesion.usuario), 'PAGE', paginas.currentWidget().objectName(), flush=True)\n# Pantalla de espera automática")
s=s.replace('acceso = DialogoAcceso(sesion, ventana)', "acceso = DialogoAcceso(sesion, ventana)\nQTimer.singleShot(6000, lambda: print('ANDROID_QA_HOME_FITS', all(a.verticalScrollBar().maximum()==0 for a in ventana.findChildren(QScrollArea) if a.isVisible()), flush=True))")
s=s.replace("acceso = DialogoAcceso(sesion, ventana)", "\ndef _qa_paginas_adaptadas():\n    correcto=True\n    for nombre in ('pagina_configuracion','pagina_productos','pagina_usuarios','pagina_clientes','pagina_inventario','pagina_historial','pagina_config_mesas','pagina_mi_cuenta'):\n        pagina=globals()[nombre]\n        paginas.setCurrentWidget(pagina)\n        if hasattr(pagina,'actualizar'):pagina.actualizar()\n        for _ in range(4):app.processEvents();adaptacion_android.aplicar()\n        recorridos=[(a.verticalScrollBar().maximum(),a.horizontalScrollBar().maximum()) for a in pagina.findChildren(QScrollArea) if a.isVisible()]\n        cabe=all(x==0 and y==0 for x,y in recorridos)\n        correcto=correcto and cabe\n        print('ANDROID_QA_PAGE',nombre,cabe,recorridos,flush=True)\n        pagina.grab().save('android-qa-'+nombre+'.png')\n    abrir_inicio()\n    print('ANDROID_QA_PAGES_FIT',correcto,flush=True)\nQTimer.singleShot(8000,_qa_paginas_adaptadas)\n" + "\nacceso = DialogoAcceso(sesion, ventana)")
p.write_text(s)
